import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { supabaseAdmin } from "./supabase-admin";

export const ADMIN_SESSION_COOKIE = "crm_session";
export const ADMIN_SESSION_MAX_AGE = 60 * 60 * 8;

const ADMIN_SESSION_TABLE = "admin_sessions";

const getSessionSecret = () => {
	const secret = import.meta.env.ADMIN_SESSION_SECRET;

	if (!secret || secret.length < 32) {
		throw new Error("ADMIN_SESSION_SECRET debe tener al menos 32 caracteres");
	}

	return secret;
};

const sign = (value: string) =>
	createHmac("sha256", getSessionSecret()).update(value).digest("base64url");

const parseAdminSession = (token?: string) => {
	if (!token) return null;

	const parts = token.split(".");
	if (parts.length !== 3) return null;

	const [expiresAt, sessionId, signature] = parts;
	if (!/^\d+$/.test(expiresAt) || !sessionId || !signature) return null;

	const expiresAtNumber = Number(expiresAt);
	if (expiresAtNumber <= Math.floor(Date.now() / 1000)) return null;

	const payload = `${expiresAt}.${sessionId}`;
	const expected = Buffer.from(sign(payload));
	const received = Buffer.from(signature);

	if (expected.length !== received.length || !timingSafeEqual(expected, received)) {
		return null;
	}

	return {
		expiresAt: expiresAtNumber,
		sessionId,
		token: `${payload}.${signature}`,
	};
};

export const createAdminSession = async () => {
	const expiresAt = Math.floor(Date.now() / 1000) + ADMIN_SESSION_MAX_AGE;
	const sessionId = randomBytes(24).toString("base64url");
	const payload = `${expiresAt}.${sessionId}`;
	const token = `${payload}.${sign(payload)}`;

	const { error } = await supabaseAdmin.from(ADMIN_SESSION_TABLE).insert({
		session_id: sessionId,
		expires_at: new Date(expiresAt * 1000).toISOString(),
	});

	if (error) {
		throw new Error("No se pudo registrar la sesion de administrador");
	}

	return token;
};

export const verifyAdminSession = (token?: string) =>
	parseAdminSession(token) !== null;

export const isAdminSessionActive = async (token?: string) => {
	const session = parseAdminSession(token);

	if (!session) return false;

	const { data, error } = await supabaseAdmin
		.from(ADMIN_SESSION_TABLE)
		.select("session_id")
		.eq("session_id", session.sessionId)
		.is("revoked_at", null)
		.gt("expires_at", new Date().toISOString())
		.maybeSingle();

	return !error && Boolean(data);
};

export const revokeAdminSession = async (token?: string) => {
	const session = parseAdminSession(token);

	if (!session) return;

	const { error } = await supabaseAdmin
		.from(ADMIN_SESSION_TABLE)
		.update({ revoked_at: new Date().toISOString() })
		.eq("session_id", session.sessionId)
		.is("revoked_at", null);

	if (error) {
		throw new Error("No se pudo invalidar la sesion de administrador");
	}
};

